const resposta = $input.first().json;

// Recupera o que o usuário pesquisou no formulário
const pesquisa = $('01 - Receber Pesquisa').first().json.produto || '';

// Lojas e marketplaces aceitos
const lojasPermitidas = [
  'net computadores',
  'kabum',
  'amazon.com.br',
  'amazon',
  'mercado livre',
  'mercadolivre',
  'magalu',
  'magazine luiza',
  'pichau',
  'terabyte',
  'terabyte shop',
  'patoloco',
  'gk infostore',
  'waz',
  'login informática',
  'login informatica',
  'guerra digital',
  'oficina dos bits',
  'chipart',
  'casas bahia',
  'fast shop'
];

// Normaliza textos
function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Normaliza a pesquisa e o título dos produtos
function normalizarModelo(texto) {
  return normalizar(texto)
    .replace(/\brtx\s*(\d{4})\b/g, 'rtx $1')
    .replace(/\b(\d+)\s*gb\b/g, '$1gb');
}

const pesquisaNormalizada = normalizarModelo(pesquisa);

// Identifica o número do modelo pesquisado
const modeloPesquisa = pesquisaNormalizada.match(/\brtx\s*(\d{4})\b/);

// Identifica variantes solicitadas
const pesquisaTi = /\bti\b/.test(pesquisaNormalizada);
const pesquisaSuper = /\bsuper\b/.test(pesquisaNormalizada);

// Identifica a memória solicitada, se houver
const memoriaPesquisa = pesquisaNormalizada.match(/\b(\d+)gb\b/);

// Produtos retornados pelo Serper
const produtos = resposta.shopping || [];

// Organiza os dados e converte os preços
const ofertas = produtos.map(produto => {
  const precoTexto = produto.price || '';
  const tituloOriginal = produto.title || '';

  // Procura possíveis códigos de fabricante no título
  const codigosEncontrados = tituloOriginal.match(
    /[A-Z0-9-]{8,25}/gi
  ) || [];

  // Mantém somente sequências que tenham letras e números
  const codigosValidos = codigosEncontrados.filter(codigo => {
    const temLetra = /[A-Z]/i.test(codigo);
    const temNumero = /[0-9]/.test(codigo);

    return temLetra && temNumero;
  });

  // Seleciona o último código encontrado
  const codigoModelo = codigosValidos.length > 0
    ? codigosValidos[codigosValidos.length - 1].toUpperCase()
    : null;

  // Converte o preço para número
  const correspondencia = precoTexto.match(/[\d.]+,\d{2}/);

  let precoNumerico = null;

  if (correspondencia) {
    precoNumerico = Number(
      correspondencia[0]
        .replace(/\./g, '')
        .replace(',', '.')
    );
  }

  // Identifica o tipo de link
  const link = produto.link || '';

  let tipoLink = 'Sem link disponível';

  if (link.includes('google.com/search?ibp=oshop')) {
    tipoLink = 'Google Shopping';
  } else if (link) {
    tipoLink = 'Link direto';
  }

  return {
    titulo: produto.title || 'Produto sem nome',
    loja: produto.source || 'Loja não informada',
    preco: precoTexto,
    precoNumerico,
    link,
    tipoLink,
    codigoModelo,
    imagem: produto.imageUrl || ''
  };
});

// Mantém somente lojas permitidas
const ofertasBrasileiras = ofertas.filter(produto => {
  const loja = normalizar(produto.loja);

  return lojasPermitidas.some(nome =>
    loja.includes(normalizar(nome))
  );
});

// Filtra os modelos para corresponder à pesquisa
const ofertasRelevantes = ofertasBrasileiras.filter(produto => {
  const titulo = normalizarModelo(produto.titulo);

  // Exclui computadores e equipamentos completos
  const termosEquipamentoCompleto = [
    'computador',
    'pc gamer',
    'pc completo',
    'computador gamer',
    'notebook',
    'laptop',
    'desktop',
    'cpu gamer',
    'cpu intel',
    'cpu amd',
    'gabinete gamer',
    'setup gamer',
    'kit gamer',
    'ryzen 5',
    'ryzen 7',
    'ryzen 9',
    'intel core i3',
    'intel core i5',
    'intel core i7',
    'intel core i9',
    'processador'
  ];

  const equipamentoCompleto = termosEquipamentoCompleto.some(
    termo => titulo.includes(termo)
  );

  if (equipamentoCompleto) {
    return false;
  }

  // Confere o número exato do modelo
  if (modeloPesquisa) {
    const numeroModelo = modeloPesquisa[1];
    const regexModelo = new RegExp(`\\brtx\\s*${numeroModelo}\\b`);

    if (!regexModelo.test(titulo)) {
      return false;
    }
  }

  // Se a pesquisa não pediu Ti, exclui produtos Ti
  const produtoTi = /\bti\b/.test(titulo);

  if (produtoTi !== pesquisaTi) {
    return false;
  }

  // Se a pesquisa não pediu Super, exclui produtos Super
  const produtoSuper = /\bsuper\b/.test(titulo);

  if (produtoSuper !== pesquisaSuper) {
    return false;
  }

  // Se a pesquisa informou memória, exige essa memória no título
  if (memoriaPesquisa) {
    const memoriaProduto = new RegExp(
      `\\b${memoriaPesquisa[1]}gb\\b`
    );

    if (!memoriaProduto.test(titulo)) {
      return false;
    }
  }

  return true;
});

// Remove ofertas sem preço
const ofertasComPreco = ofertasRelevantes.filter(
  produto => produto.precoNumerico !== null
);

// Remove duplicações da mesma oferta
const ofertasSemDuplicatas = ofertasComPreco.filter(
  (produto, indice, lista) =>
    lista.findIndex(outro =>
      normalizar(outro.titulo) === normalizar(produto.titulo) &&
      normalizar(outro.loja) === normalizar(produto.loja) &&
      outro.precoNumerico === produto.precoNumerico
    ) === indice
);

// Ordena do menor para o maior preço
const ofertasOrdenadas = ofertasSemDuplicatas.sort(
  (a, b) => a.precoNumerico - b.precoNumerico
);

// Adiciona a posição no ranking final
return ofertasOrdenadas.map((oferta, indice) => ({
  json: {
    posicao: indice + 1,
    ...oferta
  }
}));

const itens = $input.all();

// Domínios oficiais das lojas aceitas
const dominiosLojas = [
  { nome: 'amazon', dominio: 'amazon.com.br' },
  { nome: 'mercado livre', dominio: 'mercadolivre.com.br' },
  { nome: 'mercadolivre', dominio: 'mercadolivre.com.br' },
  { nome: 'kabum', dominio: 'kabum.com.br' },
  { nome: 'pichau', dominio: 'pichau.com.br' },
  { nome: 'terabyte', dominio: 'terabyteshop.com.br' },
  { nome: 'magalu', dominio: 'magazineluiza.com.br' },
  { nome: 'magazine luiza', dominio: 'magazineluiza.com.br' },
  { nome: 'patoloco', dominio: 'patoloco.com.br' },
  { nome: 'gk infostore', dominio: 'gkinfostore.com.br' },
  { nome: 'waz', dominio: 'waz.com.br' },
  { nome: 'login informatica', dominio: 'login.com.br' },
  { nome: 'guerra digital', dominio: 'gueradigital.com.br' },
  { nome: 'oficina dos bits', dominio: 'oficinadosbits.com.br' },
  { nome: 'chipart', dominio: 'chipart.com.br' },
  { nome: 'casas bahia', dominio: 'casasbahia.com.br' },
  { nome: 'fast shop', dominio: 'fastshop.com.br' }
];

// Normaliza textos
function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Identifica o domínio esperado pela loja
function identificarDominio(loja) {
  const nome = normalizar(loja);

  const correspondencia = dominiosLojas.find(item =>
    nome.includes(normalizar(item.nome))
  );

  return correspondencia ? correspondencia.dominio : null;
}

// Extrai características importantes do produto
function extrairCaracteristicas(titulo) {
  const texto = normalizar(titulo);

  const modelo = texto.match(/\brtx\s*(\d{4})\b/);
  const memoria = texto.match(/\b(8|12|16|24|32)\s*gb\b/);

  return {
    modelo: modelo ? modelo[1] : null,
    memoria: memoria ? memoria[1] : null,
    ti: /\bti\b/.test(texto),
    super: /\bsuper\b/.test(texto)
  };
}

// Analisa o endereço sem depender de new URL()
function analisarLink(link) {
  const linkLimpo = String(link || '').trim();

  const partes = linkLimpo.match(
    /^https?:\/\/([^/:?#]+)(?::\d+)?(\/[^?#]*)?/i
  );

  if (!partes) {
    return null;
  }

  return {
    dominio: partes[1].toLowerCase(),
    caminho: partes[2] || ''
  };
}

// Lista de marcas conhecidas
const marcas = [
  'peladn',
  'pcyes',
  'galax',
  'msi',
  'asus',
  'gigabyte',
  'zotac',
  'gainward',
  'palit',
  'loongscale',
  'inno3d',
  'pny',
  'sapphire',
  'xfx',
  'powercolor'
];

// Valida se o resultado corresponde à oferta original
function validarResultado(oferta, resultado, dominioEsperado) {
  if (!resultado || !resultado.link || !dominioEsperado) {
    return false;
  }

  const linkAnalisado = analisarLink(resultado.link);

  if (!linkAnalisado) {
    return false;
  }

  const dominioEncontrado = linkAnalisado.dominio;
  const caminho = linkAnalisado.caminho;

  // Confere o domínio da loja
  if (
    dominioEncontrado !== dominioEsperado &&
    !dominioEncontrado.endsWith('.' + dominioEsperado)
  ) {
    return false;
  }

  // Aceita somente páginas de produto
  if (!/\/dp\/|\/p\//i.test(caminho)) {
    return false;
  }

  const original = extrairCaracteristicas(oferta.titulo);

  const encontrado = extrairCaracteristicas(
    resultado.title + ' ' + (resultado.snippet || '')
  );

  // Exige o mesmo modelo RTX
  if (!original.modelo || original.modelo !== encontrado.modelo) {
    return false;
  }

  // Exige a mesma memória quando identificada
  if (
    original.memoria &&
    original.memoria !== encontrado.memoria
  ) {
    return false;
  }

  // Confere Ti e Super
  if (original.ti !== encontrado.ti) {
    return false;
  }

  if (original.super !== encontrado.super) {
    return false;
  }

  // Confere a marca quando identificada na oferta
  const textoOriginal = normalizar(oferta.titulo);

  const textoEncontrado = normalizar(
    resultado.title + ' ' + (resultado.snippet || '')
  );

  const marcaOriginal = marcas.find(marca =>
    textoOriginal.includes(marca)
  );

  if (
    marcaOriginal &&
    !textoEncontrado.includes(marcaOriginal)
  ) {
    return false;
  }

  return true;
}

// Processa cada oferta
return itens.map(item => {
  const oferta = item.json;

  const dominioEsperado = identificarDominio(oferta.loja);

  const resultados = Array.isArray(oferta.organic)
    ? oferta.organic
    : [];

  // Procura o primeiro resultado que passe em todas as validações
  const resultadoValido = resultados.find(resultado =>
    validarResultado(oferta, resultado, dominioEsperado)
  );

  return {
    json: {
      ...oferta,

      linkDireto: resultadoValido
        ? resultadoValido.link
        : null,

      tituloLinkValidado: resultadoValido
        ? resultadoValido.title
        : null,

      tipoLinkFinal: resultadoValido
        ? 'Link direto validado'
        : 'Link do Google Shopping',

      linkFinal: resultadoValido
        ? resultadoValido.link
        : oferta.link,

      validacaoLink: resultadoValido
        ? 'Correspondência encontrada'
        : 'Nenhuma correspondência confiável encontrada',

      dominioEsperado
    }
  };
});

const itens = $input.all();

// Escapa caracteres especiais para evitar problemas no HTML
function escaparHTML(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Converte o preço para número
function obterPrecoNumerico(oferta) {
  if (typeof oferta.precoNumerico === 'number') {
    return oferta.precoNumerico;
  }

  const texto = String(oferta.preco || '');
  const encontrado = texto.match(/[\d.]+,\d{2}/);

  if (!encontrado) return null;

  return Number(
    encontrado[0]
      .replace(/\./g, '')
      .replace(',', '.')
  );
}

// Formata o preço em reais
function formatarPreco(oferta) {
  const valor = obterPrecoNumerico(oferta);

  if (valor !== null && Number.isFinite(valor)) {
    return valor.toLocaleString('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    });
  }

  return oferta.preco || 'Preço não informado';
}

// Descobre a oferta mais barata
const precos = itens
  .map(item => obterPrecoNumerico(item.json))
  .filter(valor => valor !== null && Number.isFinite(valor));

const menorPreco = precos.length
  ? Math.min(...precos)
  : null;

// Monta os cartões dos produtos
const cartoes = itens.map((item, indice) => {
  const oferta = item.json;

  const titulo = escaparHTML(oferta.titulo || 'Produto sem título');
  const loja = escaparHTML(oferta.loja || 'Loja não informada');
  const preco = escaparHTML(formatarPreco(oferta));
  const valorNumerico = obterPrecoNumerico(oferta);

  // Procura a imagem do produto
  const imagemOriginal = oferta.imagem || oferta.imageUrl || '';
  const imagem = /^https?:\/\/[^\s"'<>]+$/i.test(String(imagemOriginal))
    ? escaparHTML(imagemOriginal)
    : '';

  // Valida o link de acesso
  const linkOriginal = String(oferta.linkFinal || '').trim();
  const linkSeguro = /^https?:\/\/[^\s"'<>]+$/i.test(linkOriginal)
    ? escaparHTML(linkOriginal)
    : '';

  const tipoLink = escaparHTML(
    oferta.tipoLinkFinal || 'Link de acesso'
  );

  const maisBarato =
    menorPreco !== null &&
    valorNumerico !== null &&
    valorNumerico === menorPreco;

  return `
    <article class="produto">

      <div class="produto-topo">
        <span class="numero">OFERTA ${indice + 1}</span>
        ${
          maisBarato
            ? '<span class="selo">MENOR PREÇO</span>'
            : ''
        }
      </div>

      <div class="imagem-container">
        ${
          imagem
            ? `<img
                class="imagem-produto"
                src="${imagem}"
                alt="${titulo}"
                loading="lazy"
                onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
              >
              <div class="imagem-fallback" style="display:none;">
                <span>Imagem indisponível</span>
              </div>`
            : `<div class="imagem-fallback">
                <span>Imagem indisponível</span>
              </div>`
        }
      </div>

      <div class="produto-info">
        <h2>${titulo}</h2>

        <p class="loja">
          <span class="icone-loja">▣</span>
          ${loja}
        </p>

        <div class="preco-container">
          <span class="preco-legenda">Preço anunciado</span>
          <p class="preco">${preco}</p>
        </div>

        <div class="rodape-card">
          <span class="tipo-link">${tipoLink}</span>

          ${
            linkSeguro
              ? `<a
                  class="botao"
                  href="${linkSeguro}"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Ver oferta <span>↗</span>
                </a>`
              : `<span class="botao-indisponivel">
                  Link indisponível
                </span>`
          }
        </div>
      </div>

    </article>
  `;
}).join('');

// Resumo da pesquisa
const resumoMenorPreco = menorPreco !== null
  ? menorPreco.toLocaleString('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    })
  : 'Não disponível';

// Página HTML
const html = `
