<html lang="pt-BR">

<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>TechFinder | Resultados</title>

<style>
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    padding: 0;
    background: #f5f7fc;
    font-family: Arial, Helvetica, sans-serif;
    color: #172033;
  }

  .pagina {
    min-height: 100vh;
  }

  /* CABEÇALHO */

  .cabecalho {
    background: linear-gradient(120deg, #102b63, #1746a2, #2563eb);
    padding: 32px 24px 42px;
    color: white;
  }

  .cabecalho-conteudo {
    max-width: 1180px;
    margin: auto;
  }

  .marca {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 34px;
  }

  .logo {
    width: 42px;
    height: 42px;
    border-radius: 12px;
    background: rgba(255,255,255,0.16);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 23px;
    font-weight: bold;
  }

  .marca h1 {
    margin: 0;
    font-size: 25px;
    letter-spacing: -0.7px;
  }

  .marca span {
    display: block;
    font-size: 11px;
    color: #c8d8ff;
    margin-top: 3px;
    letter-spacing: 1.5px;
    text-transform: uppercase;
  }

  .titulo-pagina {
    margin: 0;
    font-size: 30px;
    letter-spacing: -0.8px;
  }

  .subtitulo {
    margin: 10px 0 0;
    color: #dbe7ff;
    font-size: 15px;
  }

  /* CONTEÚDO */

  .conteudo {
    max-width: 1180px;
    margin: -20px auto 0;
    padding: 0 24px 50px;
    position: relative;
  }

  /* RESUMO */

  .resumo {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
    margin-bottom: 30px;
  }

  .resumo-card {
    background: white;
    border: 1px solid #e6eaf2;
    border-radius: 13px;
    padding: 19px 22px;
    box-shadow: 0 5px 18px rgba(20, 40, 80, 0.06);
  }

