    color: #718096;
    font-size: 13px;
    margin-bottom: 8px;
  }

  .resumo-valor {
    color: #183b80;
    font-size: 23px;
    font-weight: 700;
  }

  .resumo-card.destaque .resumo-valor {
    color: #07834d;
  }

  /* LISTA DE PRODUTOS */

  .secao-titulo {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
  }

  .secao-titulo h2 {
    margin: 0;
    font-size: 20px;
    color: #1c2c48;
  }

  .ordenacao {
    color: #718096;
    font-size: 12px;
  }

  .produtos {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
  }

  /* CARTÃO */

  .produto {
    background: white;
    border: 1px solid #e5eaf3;
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 5px 18px rgba(25, 45, 85, 0.045);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  .produto:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 26px rgba(25, 45, 85, 0.10);
  }

  .produto-topo {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px 17px 0;
    min-height: 35px;
  }

  .numero {
    color: #718096;
    font-size: 10px;
    font-weight: bold;
    letter-spacing: 1px;
  }

  .selo {
    color: #087a49;
    background: #e6f7ee;
    padding: 6px 9px;
    border-radius: 20px;
    font-size: 9px;
    font-weight: bold;
    letter-spacing: 0.5px;
  }

  /* IMAGEM */

  .imagem-container {
    height: 175px;
    padding: 14px 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff;
  }

  .imagem-produto {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }

  .imagem-fallback {
    width: 100%;
    height: 100%;
    background: #f3f6fb;
    border: 1px dashed #d5deed;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    font-size: 12px;
  }

  /* INFORMAÇÕES */

  .produto-info {
    padding: 17px 19px 20px;
    border-top: 1px solid #f0f2f7;
  }

  .produto h2 {
    font-size: 15px;
    line-height: 1.5;
    font-weight: 700;
    color: #202e45;
    margin: 0 0 13px;
    min-height: 67px;
  }

  .loja {
    color: #718096;
    font-size: 12px;
    margin: 0 0 18px;
  }

  .icone-loja {
    color: #2563eb;
    margin-right: 5px;
  }

  .preco-container {
    border-top: 1px solid #edf0f5;
    padding-top: 14px;
  }

  .preco-legenda {
    color: #8a96a9;
    font-size: 11px;
  }

  .preco {
    color: #07834d;
    font-size: 25px;
    font-weight: 800;
    letter-spacing: -0.7px;
    margin: 5px 0 16px;
  }

  .rodape-card {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .tipo-link {
    color: #718096;
    font-size: 11px;
  }

  .botao {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    padding: 12px;
    border-radius: 8px;
    background: #2563eb;
    color: white;
    text-decoration: none;
    font-size: 13px;
    font-weight: bold;
    transition: background 0.2s ease;
  }

  .botao:hover {
    background: #1746b5;
  }

  .botao-indisponivel {
    display: block;
    text-align: center;
    padding: 12px;
    border-radius: 8px;
    background: #f1f3f7;
    color: #8a96a9;
    font-size: 12px;
  }

  /* RODAPÉ */

  .rodape {
    max-width: 1180px;
    margin: 0 auto;
    padding: 20px 24px 30px;
    border-top: 1px solid #e4e9f1;
    color: #8995a8;
    font-size: 11px;
    text-align: center;
  }

  /* RESPONSIVIDADE */

  @media (max-width: 900px) {
    .produtos {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 580px) {
    .cabecalho {
      padding: 25px 18px 38px;
    }

    .titulo-pagina {
      font-size: 24px;
    }

    .conteudo {
      padding: 0 14px 35px;
    }

    .resumo {
      gap: 10px;
    }

    .resumo-card {
      padding: 15px;
    }

    .resumo-valor {
      font-size: 18px;
    }

    .produtos {
      grid-template-columns: 1fr;
    }

    .imagem-container {
      height: 190px;
    }

    .produto h2 {
      min-height: auto;
    }
  }
</style>
</head>

<body>

<div class="pagina">

  <header class="cabecalho">
    <div class="cabecalho-conteudo">

      <div class="marca">
        <div class="logo">T</div>
        <div>
          <h1>TechFinder</h1>
          <span>Compare. Encontre. Economize.</span>
        </div>
      </div>

      <h2 class="titulo-pagina">
        Resultados da sua pesquisa
      </h2>

      <p class="subtitulo">
        Encontramos ofertas para você comparar.
      </p>

    </div>
  </header>

  <main class="conteudo">

    <section class="resumo">

      <div class="resumo-card">
        <div class="resumo-label">Ofertas encontradas</div>
        <div class="resumo-valor">${itens.length}</div>
      </div>

      <div class="resumo-card destaque">
        <div class="resumo-label">Menor preço encontrado</div>
        <div class="resumo-valor">${resumoMenorPreco}</div>
      </div>

    </section>

    <section>

      <div class="secao-titulo">
        <h2>Ofertas disponíveis</h2>
        <span class="ordenacao">Compare as opções</span>
      </div>

      <div class="produtos">

        ${
          cartoes ||
          '<p>Nenhuma oferta foi encontrada para sua pesquisa.</p>'
        }

      </div>

    </section>

  </main>

  <footer class="rodape">
    TechFinder © 2026 — Pesquisa e comparação de preços.
    Preços e condições podem mudar. Confira os detalhes na loja.
  </footer>

</div>

</body>
</html>
`;

return [
  {
    json: {
      html,
      totalOfertas: itens.length
    }
  }
];
